sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	verifyEmails(String(current.subject),gs.getMessage("Following variables in subject are not valid:"),false);
	verifyEmails(String(current.message_html),gs.getMessage("Following variables are not valid or defined:"),true);

	function verifyEmails(content,message,setBody) {
		var hrform = new sn_hr_core.GeneralHRForm();
		var body = hrform.validateTemplate(content, current.table, true);
		if(setBody)
			current.message_html = body;
		var unEvaluatedVariables = hrform.unEvaluatedVariable;
		if (unEvaluatedVariables && unEvaluatedVariables.length > 0)
			throwError(message,unEvaluatedVariables);
	}

	function throwError(message,unevaluatedVariables) {
		for (var i=0; i<unevaluatedVariables.length; i++) {
			message += ' ' + unevaluatedVariables[i];
			if (i != unevaluatedVariables.length - 1)
			message += ',';
		}
		gs.addErrorMessage(message);
		current.setAbortAction(true);
	}

})(current, previous);
